{"kind":"tool","id":"eLBNy88egDY","toolName":"write_file","input":{"path":"client/src/test/helpers.tsx","instructions":"Test helpers: render with providers and override setup state.","content":"import { useEffect, type ReactNode } from 'react';
import { render } from '@testing-library/react';
import { NavigationProvider } from '../nav/navigation';
import { SetupProvider, useSetup, type FlowIntent } from '../state/setup';

/** Renders UI inside the providers every screen runs under in the real app. */
export function renderWithProviders(ui: ReactNode) {
  return render(
    <SetupProvider>
      <NavigationProvider>{ui}</NavigationProvider>
    </SetupProvider>,
  );
}

/**
 * Applies setup-state overrides before the assertion runs — lets a test reach
 * e.g. an empty nickname or the join intent without a UI detour.
 */
export function SetupOverride({
  nickname,
  intent,
}: {
  nickname?: string;
  intent?: FlowIntent;
}) {
  const { setNickname, setIntent } = useSetup();

  useEffect(() => {
    if (nickname !== undefined) setNickname(nickname);
    if (intent !== undefined) setIntent(intent);
  }, [nickname, intent, setNickname, setIntent]);

  return null;
}
